function square(s) { return s * s; }
function circle(r) { return Math.PI * r * r; }
function triangleOld(b, h) { return b * h; }
function legacyPerimeter(s) { return 4 * s; }
function area(shape) {
	return shape.kind === 'square' ? square(shape.size) : circle(shape.size);
}
module.exports = { area };

